import { Input } from '@mantine/core';
import { useId } from '@mantine/hooks';
import classes from './NativeTextInput.module.css';

interface NativeTextInputProps {
  label?: string;
  placeholder?: string;
  value?: string;
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  onFocus?: (event: React.FocusEvent<HTMLInputElement>) => void;
  onBlur?: (event: React.FocusEvent<HTMLInputElement>) => void;
  error?: React.ReactNode;
}

export function NativeTextInput({ label, error, ...inputProps }: NativeTextInputProps) {
  const id = useId();

  return (
    <Input.Wrapper id={id} size="md" label={label} error={error}>
      <input id={id} className={classes.nativeInput} aria-invalid={!!error} {...inputProps} />
    </Input.Wrapper>
  );
}

import { StarIcon } from '@phosphor-icons/react';
import { Group, Input, UnstyledButton } from '@mantine/core';
import { useFormField, useId } from '@mantine/hooks';

interface StarRatingProps {
  label?: string;
  value?: number;
  onChange?: (value: number) => void;
  onFocus?: () => void;
  onBlur?: () => void;
  error?: React.ReactNode;
  'data-path'?: string;
}

export function StarRating({
  label,
  value,
  onChange,
  onFocus,
  onBlur,
  error,
  'data-path': dataPath,
}: StarRatingProps) {
  const id = useId();
  const field = useFormField<number>(onChange);
  const current = (field.subscribed ? field.value : value) ?? 0;

  const stars = [1, 2, 3, 4, 5].map((star) => {
    const active = star <= current;
    return (
      <UnstyledButton
        key={star}
        type="button"
        aria-label={`${star} ${star === 1 ? 'star' : 'stars'}`}
        display="flex"
        data-path={star === 1 ? dataPath : undefined}
        onClick={() => onChange?.(star)}
        onFocus={onFocus}
        onBlur={onBlur}
      >
        <StarIcon
          size={28}
          weight={active ? 'fill' : 'regular'}
          color={active ? 'var(--mantine-color-yellow-5)' : 'var(--mantine-color-gray-5)'}
        />
      </UnstyledButton>
    );
  });

  return (
    <Input.Wrapper id={id} size="md" label={label} labelElement="div" error={error} withAsterisk>
      <Group role="group" aria-labelledby={`${id}-label`} gap={2} mt={4} mb={error ? 6 : 0}>
        {stars}
      </Group>
    </Input.Wrapper>
  );
}
